def compact_number_formatter(n: int | float) -> str:
    if n == 0:
        return '0'
    if n < 0:
        return '-' + compact_number_formatter(-n)

    suffixes = ['K', 'M', 'B']
    for suffix in suffixes:
        if abs(n) < 1000:
            break
        n /= 1000

    if n.is_integer():
        return f'{int(n)}{suffix}'
    else:
        return f'{n:.1f}{suffix}'

def time_diff_humanized(seconds: int) -> str:
    if seconds == 0:
        return '0s'

    units = []
    if seconds >= 86400:
        days = seconds // 86400
        units.append(f'{days}d')
        seconds %= 86400
    if seconds >= 3600:
        hours = seconds // 3600
        units.append(f'{hours}h')
        seconds %= 3600
    if seconds >= 60:
        minutes = seconds // 60
        units.append(f'{minutes}m')
        seconds %= 60
    if seconds > 0:
        units.append(f'{seconds}s')

    return ' '.join(units)

def find_first_missing_positive(nums: list[int]) -> int:
    n = len(nums)
    if 1 not in nums:
        return 1

    if n == 1:
        return 2

    nums = [0] + nums
    n += 1

    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n

    for i in range(1, n):
        index = abs(nums[i])
        if index < n:
            nums[index] = -abs(nums[index])

    for i in range(1, n):
        if nums[i] > 0:
            return i

    return n

