def fuzzy_search_score(pattern: str, text: str) -> int:
    pattern = pattern.lower()
    text = text.lower()
    pattern_len = len(pattern)
    text_len = len(text)
    if pattern_len == 0 or text_len == 0:
        return 0

    score = 0
    i, j = 0, 0
    while i < pattern_len and j < text_len:
        if pattern[i] == text[j]:
            score += 10
            if i > 0 and pattern[i] == pattern[i - 1]:
                score += 15
            if j == 0 or text[j] in " _-":
                score += 20
            i += 1
        j += 1

    return score

